#!/usr/bin/env bash
# Crea las etiquetas e issues del backlog inicial con GitHub CLI (gh).
# Requisitos: gh instalado y autenticado (gh auth login). Ejecutar dentro del repositorio.
# Si el tablero ya existe, agrega --project "Mesa de Soporte TI" a cada gh issue create
# (o usa 'Add item' > 'Add items from repository' en el tablero).
set -e
for l in H1 H2 H3 H4 FINAL historia cambio riesgo bloqueado; do gh label create "$l" --force >/dev/null; done

gh issue create --title "T01 · Definir problema, objetivo y alcance v0.1" --label "H1" --body "$(printf 'Rol: Líder de Proyecto y Control\nPrioridad: Alta\nEstimación: 1.5 h\nFecha objetivo: 2026-09-29\nEvidencia: (completar con enlace/commit al cerrar)')"
gh issue create --title "T02 · Crear repositorio Git y README inicial" --label "H1" --body "$(printf 'Rol: Solución y Desarrollo\nPrioridad: Alta\nEstimación: 0.5 h\nFecha objetivo: 2026-09-29\nEvidencia: (completar con enlace/commit al cerrar)')"
gh issue create --title "T03 · Crear tablero GitHub Projects con columnas y campos" --label "H1" --body "$(printf 'Rol: Líder de Proyecto y Control\nPrioridad: Alta\nEstimación: 0.5 h\nFecha objetivo: 2026-09-29\nEvidencia: (completar con enlace/commit al cerrar)')"
